with.script:
const runs = await github.paginate(github.rest.checks.listForRef, {
  ...context.repo, ref: context.sha, per_page: 100
});
for (const name of ['backend', 'frontend', 'browser', 'documentation', 'containers', 'tls-acceptance', 'publication-hygiene']) {
  const run = runs.filter(item => item.name === name).sort((a, b) => b.id - a.id)[0];
  if (!run || run.conclusion !== 'success') core.setFailed(`Required successful check missing: ${name}`);
}

